class Solution {
public:
    int rob1(vector<int> &nums)
    {
        int premax=0,currmax=0;
        for(int i=1;i<nums.size();i++)
        {
            int temp=currmax;
            currmax=max(premax+nums[i],currmax);
            premax=temp;
        }
        return currmax;
    }
    int rob2(vector<int> &nums)
    {
        int premax=0,currmax=0;
        for(int i=0;i<nums.size()-1;i++)
        {
            int temp=currmax;
            currmax=max(premax+nums[i],currmax);
            premax=temp;
        }
        return currmax;
    }
    int rob(vector<int>& nums) {
        int n=nums.size();
        if(n==1)
            return nums[0];
        return max(rob1(nums),rob2(nums));
    }
};

class Solution:
    # @param {integer[]} nums
    # @return {integer}
    def rob(self, nums):
        if not nums:
            return 0
        if len(nums) == 1:
            return nums[0]
        self.memo = {} # idx -> max robbery
        def get_max_rob(idx, droplast=False):
            if (idx, droplast) in self.memo:
                return self.memo[idx, droplast]
            if idx >= len(nums):
                return 0

            if idx == len(nums)-1:
                if droplast:
                    _max = 0
                else:
                    _max = nums[idx]
            elif idx == len(nums)-2:
                if droplast:
                    _max = nums[idx]
                else:
                    _max = max(nums[idx], nums[idx+1])
            else:
                _max = max(nums[idx]+get_max_rob(idx+2, droplast), get_max_rob(idx+1, droplast))

            self.memo[idx, droplast]= _max
            return _max
        return max(nums[0]+ get_max_rob(2, True), get_max_rob(1))

class Solution {
    public int rob(int[] nums) {
        if(nums==null || nums.length==0)
            return 0;
        if(nums.length==1)
            return nums[0];
        if(nums.length==2)
            return Math.max(nums[0],nums[1]);
        int dpZeroToNminusOne[]=new int[nums.length-1];
        int dpOneToN[]=new int[nums.length-1];
        dpZeroToNminusOne[0]=nums[0];
        dpZeroToNminusOne[1]=Math.max(nums[0],nums[1]);
        dpOneToN[0]=nums[1];
        dpOneToN[1]=Math.max(nums[1],nums[2]);
        for(int i=2;i<nums.length-1;i++){
            dpZeroToNminusOne[i]=Math.max(nums[i]+dpZeroToNminusOne[i-2],dpZeroToNminusOne[i-1]);
            dpOneToN[i]=Math.max(nums[i+1]+dpOneToN[i-2],dpOneToN[i-1]);
        }

        return Math.max(dpZeroToNminusOne[nums.length-2],dpOneToN[nums.length-2]);

    }
}
